window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-378be9d8d160adb9"]={"versions": [{"id": "FIG-378be9d8d160adb9", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Funktionales Datenfluss- und Mapping-Diagramm (QoS / Prioritätsverarbeitung im Switching-Core).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Modul <code>EthSwt</code> (Ethernet Switch Driver, MCAL/Complex Driver) gemäß IEEE 802.1Q QoS-Architektur.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des zweistufigen Prioritätsmodells für den Frame-Forwarding-Pfad:\n<ol class=\"fig-list\"><li><em>Ingress-Ebene:</em> Ermittlung der internen Priorität und Abbildung auf standardisierte Traffic Classes (TC 0..7).\n</li><li><em>Egress-Ebene:</em> Deterministische Zuordnung der Traffic Classes zu hardwarebasierten Egress-Port-Warteschlangen (<code>Queue_0</code> bis <code>Queue_n</code>).\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Ingress-Prioritätsquellen:</strong>\n<ul class=\"fig-list\"><li><code>PCP</code> (<em>Priority Code Point</em>): 3-Bit-Feld aus dem IEEE 802.1Q VLAN-Tag des eingehenden Ethernet-Frames.\n</li><li><code>Regenerated Priority</code>: Port-spezifisch neu evaluierte Priorität (z. B. über VLAN-Regeneration-Tabellen gemäß IEEE 802.1Q).\n</li><li><code>IPV</code> (<em>Internal Priority Value</em> / <em>IP Precedence/DSCP</em>): Intern definierter Prioritätswert, abgeleitet aus L3/L4-Headern oder Switch-internen Port-Defaults.\n</li></ul>\n</li><li><strong>Funktionsblöcke &amp; Zwischenentitäten:</strong>\n<ul class=\"fig-list\"><li><code>Determination of priority</code>: Hardware-/Treiber-Entscheidungslogik am Ingress-Port zur Auswahl/Berechnung der maßgeblichen Rahmenpriorität.\n</li><li><code>Traffic class (TC) 0..7</code>: Interne, normalisierte Verkehrsklassen (Abstraktionsschicht zwischen Frame-Priorität und physischer Hardware-Queue; Kardinalität: 8 logische Klassen, TC_0 bis TC_7).\n</li></ul>\n</li><li><strong>Egress-Entitäten &amp; Mappings:</strong>\n<ul class=\"fig-list\"><li><code>Egress Port</code>: Physischer Ausgangsport des Ethernet-Switches mit hardwareunterstützten Sende-Warteschlangen.\n</li><li><code>TC_x maps to Queue_x</code>: Statische oder konfigurierbare 1:1-Relation von der Traffic Class zur physikalischen Egress-Queue (<code>Queue_0</code> .. <code>Queue_7</code>).\n</li></ul>\n</li><li><strong>AUTOSAR BSW-Konfigurationscontainer (ARXML):</strong>\n<ul class=\"fig-list\"><li>Ingress: <code>EthSwtPortTrafficClassAssignment</code> bzw. <code>EthSwtPriorityTrafficClassAssignment</code>.\n</li><li>Egress: <code>EthSwtTrafficClassQueueAssignment</code> (Zuordnung von TC zu Hardware-Queue).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Frame-Ingress &amp; Header-Parsing:</strong>\n<ul class=\"fig-list\"><li>Empfang des Ethernet-Frames am Ingress-Port; hardwareseitige Extraktion von PCP, DSCP/IPV oder Zuordnung der Default-Port-Priorität bei untagged Frames.\n</li></ul>\n</li><li><strong>Prioritätsbestimmung (<code>Determination of priority</code>):</strong>\n<ul class=\"fig-list\"><li>Synchroner Hardwaredurchlauf im Switch-Forwarding-Prozess.\n</li><li>Auswertung gemäß konfigurierter Ingress-Richtlinie (Priorisierung: PCP vs. IPV vs. Regenerated Priority).\n</li></ul>\n</li><li><strong>Traffic-Class-Klassifizierung:</strong>\n<ul class=\"fig-list\"><li>Mappen der ermittelten Frame-Priorität (Wertebereich 0..7) auf eine interne Traffic Class (TC 0..7) via Ingress-Port-Mapping-Tabelle.\n</li></ul>\n</li><li><strong>Egress-Port-Queuing &amp; Scheduling:</strong>\n<ul class=\"fig-list\"><li>Nach Weiterleitungsentscheidung (FDB-Lookup): Adressierung des Zielports.\n</li><li>Einreihen des Frames in die Egress-Queue <code>Queue_x</code>, die der jeweiligen <code>TC_x</code> zugewiesen ist.\n</li><li>Abarbeitung der Queues durch den Egress-Scheduler (z. B. Strict Priority, Strict Priority + Weighted Round Robin, IEEE 802.1Qav CBS).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Einschränkungen (Queue-Untermenge):</strong>\n<ul class=\"fig-list\"><li>Bietet die Switch-Hardware weniger als 8 Egress-Queues (z. B. 4 Queues gemäß Tab. 7.4), schreibt AUTOSAR vor, dass zwingend eine aufsteigende, lückenlose Untermenge beginnend bei <code>TC 0</code> (<code>Queue 0</code>) verwendet werden muss. Höhere TCs müssen entsprechend gebündelt oder auf verfügbare Queues gefaltet werden.\n</li></ul>\n</li><li><strong>Konfigurations-Constraints &amp; Deprecations:</strong>\n<ul class=\"fig-list\"><li><code>[SWS_EthSwt_00133]</code> ist als <strong>OBSOLETE</strong> markiert und durch <code>[SWS_EthSwt_CONSTR_00495]</code> ersetzt: Die Zuordnung von Ingress-Priorität zu TC erfolgt exklusiv entweder über <code>EthSwtPortTrafficClassAssignment</code> oder <code>EthSwtPriorityTrafficClassAssignment</code>. Eine redundante oder widersprüchliche Mischkonfiguration führt zu Validierungsfehlern im Generierungslauf.\n</li></ul>\n</li><li><strong>Laufzeit- &amp; Echtzeitaspekte (TSN/QoS):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass zeitkritische Frames (z. B. PTP/IEEE 802.1AS via <code>EthIf</code>/<code>EthTSyn</code> oder AVB/TSN-Streams) auf die höchste Traffic Class gemappt werden, die der höchsten prioritären Hardware-Queue zugeordnet ist, um Head-of-Line-Blocking und Jitter durch Bulk-Traffic (<code>TC 0</code>) zu verhindern.\n</li></ul>\n</li></ul>"}, {"id": "FIG-0145db8eaf1f0312", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Funktionales Datenfluss- und Mapping-Diagramm (QoS / Prioritätsverarbeitung im Switching-Core).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Modul <code>EthSwt</code> (Ethernet Switch Driver, MCAL/Complex Driver) gemäß IEEE 802.1Q QoS-Architektur.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des zweistufigen Prioritätsmodells für den Frame-Forwarding-Pfad:\n<ol class=\"fig-list\"><li><em>Ingress-Ebene:</em> Ermittlung der internen Priorität und Abbildung auf standardisierte Traffic Classes (TC 0..7).\n</li><li><em>Egress-Ebene:</em> Deterministische Zuordnung der Traffic Classes zu hardwarebasierten Egress-Port-Warteschlangen (<code>Queue_0</code> bis <code>Queue_n</code>).\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Ingress-Prioritätsquellen:</strong>\n<ul class=\"fig-list\"><li><code>Regenerated Priority</code>: Port-spezifisch neu evaluierte Priorität (z. B. über VLAN-Regeneration-Tabellen gemäß IEEE 802.1Q).\n</li><li><code>IPV</code> (<em>Internal Priority Value</em> / <em>IP Precedence/DSCP</em>): Intern definierter Prioritätswert, abgeleitet aus L3/L4-Headern oder Switch-internen Port-Defaults.\n</li></ul>\n</li><li><strong>Funktionsblöcke &amp; Zwischenentitäten:</strong>\n<ul class=\"fig-list\"><li><code>Determination of priority</code>: Hardware-/Treiber-Entscheidungslogik am Ingress-Port zur Auswahl/Berechnung der maßgeblichen Rahmenpriorität.\n</li><li><code>Traffic class (TC) 0..7</code>: Interne, normalisierte Verkehrsklassen (Abstraktionsschicht zwischen Frame-Priorität und physischer Hardware-Queue; Kardinalität: 8 logische Klassen, TC_0 bis TC_7).\n</li></ul>\n</li><li><strong>Egress-Entitäten &amp; Mappings:</strong>\n<ul class=\"fig-list\"><li><code>Egress Port</code>: Physischer Ausgangsport des Ethernet-Switches mit hardwareunterstützten Sende-Warteschlangen.\n</li><li><code>TC_x maps to Queue_x</code>: Statische oder konfigurierbare 1:1-Relation von der Traffic Class zur physikalischen Egress-Queue (<code>Queue_0</code> .. <code>Queue_7</code>).\n</li></ul>\n</li><li><strong>AUTOSAR BSW-Konfigurationscontainer (ARXML):</strong>\n<ul class=\"fig-list\"><li>Ingress: <code>EthSwtPortTrafficClassAssignment</code> bzw. <code>EthSwtPriorityTrafficClassAssignment</code>.\n</li><li>Egress: <code>EthSwtTrafficClassQueueAssignment</code> (Zuordnung von TC zu Hardware-Queue).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Frame-Ingress &amp; Header-Parsing:</strong>\n<ul class=\"fig-list\"><li>Empfang des Ethernet-Frames am Ingress-Port; hardwareseitige Extraktion von DSCP/IPV oder Zuordnung der Default-Port-Priorität bei untagged Frames.\n</li></ul>\n</li><li><strong>Prioritätsbestimmung (<code>Determination of priority</code>):</strong>\n<ul class=\"fig-list\"><li>Synchroner Hardwaredurchlauf im Switch-Forwarding-Prozess.\n</li><li>Auswertung gemäß konfigurierter Ingress-Richtlinie (Priorisierung: IPV vs. Regenerated Priority).\n</li></ul>\n</li><li><strong>Traffic-Class-Klassifizierung:</strong>\n<ul class=\"fig-list\"><li>Mappen der ermittelten Frame-Priorität (Wertebereich 0..7) auf eine interne Traffic Class (TC 0..7) via Ingress-Port-Mapping-Tabelle.\n</li></ul>\n</li><li><strong>Egress-Port-Queuing &amp; Scheduling:</strong>\n<ul class=\"fig-list\"><li>Nach Weiterleitungsentscheidung (FDB-Lookup): Adressierung des Zielports.\n</li><li>Einreihen des Frames in die Egress-Queue <code>Queue_x</code>, die der jeweiligen <code>TC_x</code> zugewiesen ist.\n</li><li>Abarbeitung der Queues durch den Egress-Scheduler (z. B. Strict Priority, Strict Priority + Weighted Round Robin, IEEE 802.1Qav CBS).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Einschränkungen (Queue-Untermenge):</strong>\n<ul class=\"fig-list\"><li>Bietet die Switch-Hardware weniger als 8 Egress-Queues (z. B. 4 Queues gemäß Tab. 7.4), schreibt AUTOSAR vor, dass zwingend eine aufsteigende, lückenlose Untermenge beginnend bei <code>TC 0</code> (<code>Queue 0</code>) verwendet werden muss. Höhere TCs müssen entsprechend gebündelt oder auf verfügbare Queues gefaltet werden.\n</li></ul>\n</li><li><strong>Konfigurations-Constraints &amp; Deprecations:</strong>\n<ul class=\"fig-list\"><li><code>[SWS_EthSwt_00133]</code> ist als <strong>OBSOLETE</strong> markiert und durch <code>[SWS_EthSwt_CONSTR_00495]</code> ersetzt: Die Zuordnung von Ingress-Priorität zu TC erfolgt exklusiv entweder über <code>EthSwtPortTrafficClassAssignment</code> oder <code>EthSwtPriorityTrafficClassAssignment</code>. Eine redundante oder widersprüchliche Mischkonfiguration führt zu Validierungsfehlern im Generierungslauf.\n</li></ul>\n</li><li><strong>Laufzeit- &amp; Echtzeitaspekte (TSN/QoS):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass zeitkritische Frames (z. B. PTP/IEEE 802.1AS via <code>EthIf</code>/<code>EthTSyn</code> oder AVB/TSN-Streams) auf die höchste Traffic Class gemappt werden, die der höchsten prioritären Hardware-Queue zugeordnet ist, um Head-of-Line-Blocking und Jitter durch Bulk-Traffic (<code>TC 0</code>) zu verhindern.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-378be9d8d160adb9", "to": "FIG-0145db8eaf1f0312", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Ingress-Prioritätsquellen / <code>PCP</code>:</strong> Das Eingangs-Element <code>PCP</code> (Priority Code Point) inklusive Verbindungspfeil zum Funktionsblock <code>Determination of priority</code> wurde entfernt; als Ingress-Eingangsgrößen verbleiben ausschließlich <code>IPV</code> und <code>Regenerated Priority</code>.\n</li></ul>"}]};
